begin;
select plan(26);
select is((select relrowsecurity from pg_class where oid='public.space_discovery_connections'::regclass),true,'RLS enabled');
select is((select bool_or(has_column_privilege('anon','public.space_discovery_connections',attname,'select')) from pg_attribute where attrelid='public.space_discovery_connections'::regclass and attnum>0 and not attisdropped),false,'anon has no column-level select grant');
select is((select bool_or(has_column_privilege('authenticated','public.space_discovery_connections',attname,'select')) from pg_attribute where attrelid='public.space_discovery_connections'::regclass and attnum>0 and not attisdropped),false,'authenticated has no column-level select grant');
select is((select count(*)::int from pg_policies where schemaname='public' and tablename='space_discovery_connections'),0,'no browser policies');
select is(has_table_privilege('anon','public.space_discovery_connections','select'),false,'anon select denied');
select is(has_table_privilege('anon','public.space_discovery_connections','insert'),false,'anon insert denied');
select is(has_table_privilege('anon','public.space_discovery_connections','update'),false,'anon update denied');
select is(has_table_privilege('anon','public.space_discovery_connections','delete'),false,'anon delete denied');
select is(has_table_privilege('authenticated','public.space_discovery_connections','select'),false,'authenticated select denied');
select is(has_table_privilege('authenticated','public.space_discovery_connections','insert'),false,'authenticated insert denied');
select is(has_table_privilege('authenticated','public.space_discovery_connections','update'),false,'authenticated update denied');
select is(has_table_privilege('authenticated','public.space_discovery_connections','delete'),false,'authenticated delete denied');
select ok(has_table_privilege('service_role','public.space_discovery_connections','select') and has_table_privilege('service_role','public.space_discovery_connections','insert') and has_table_privilege('service_role','public.space_discovery_connections','update') and has_table_privilege('service_role','public.space_discovery_connections','delete'),'service CRUD allowed');
select is((select pg_get_constraintdef(oid) from pg_constraint where conrelid='public.space_discovery_connections'::regclass and contype='p'),'PRIMARY KEY (space_id, provider)','one provider connection per Space');
insert into auth.users(id,email) values('00000000-0000-4000-b252-000000000001','discovery252@example.test');
insert into public.profiles(id,auth_user_id,display_name,handle) values('00000000-0000-4000-b252-000000000002','00000000-0000-4000-b252-000000000001','Connection test','discovery-252');
insert into public.entities(id,key,name,kind) select gen_random_uuid(),'labs','Labs','for_profit' where not exists(select 1 from public.entities where key='labs');
insert into public.spaces(id,slug,name,type,entity_id,status,visibility) values('00000000-0000-4000-b252-000000000003','discovery252','Discovery252','business',(select id from public.entities where key='labs' limit 1),'active','network');
set local role authenticated;
select throws_ok($$select * from public.space_discovery_connections$$,'42501',null,'authenticated cannot read sealed tokens');
reset role;
set local role anon;
select throws_ok($$insert into public.space_discovery_connections(space_id,provider) values('00000000-0000-4000-b252-000000000003','google_search_console')$$,'42501',null,'anon cannot create connection');
reset role;
set local role service_role;
select lives_ok($$insert into public.space_discovery_connections(space_id,provider,id,actor_profile_id,consent_id,property_url,property_scope,state,nonce_hash,nonce_expires_at,pending_ciphertext) values('00000000-0000-4000-b252-000000000003','google_search_console','00000000-0000-4000-b252-000000000004','00000000-0000-4000-b252-000000000002','grant','sc-domain:example.com','page_urls','pending',repeat('a',64),now()+interval '10 minutes','v1.fixture')$$,'service creates encrypted pending row');
with changed as (update public.space_discovery_connections set state='exchanging',nonce_hash=null,revision=2 where id='00000000-0000-4000-b252-000000000004' and state='pending' and revision=1 and nonce_hash=repeat('a',64) and nonce_expires_at>now() returning id) select is((select count(*)::int from changed),1,'pending state consumed atomically');
with changed as (update public.space_discovery_connections set state='exchanging',nonce_hash=null,revision=2 where id='00000000-0000-4000-b252-000000000004' and state='pending' and revision=1 and nonce_hash=repeat('a',64) returning id) select is((select count(*)::int from changed),0,'replayed callback cannot consume');
with changed as (update public.space_discovery_connections set state='connected',pending_ciphertext=null,nonce_expires_at=null,tokens_ciphertext='v1.tokens',expires_at=now()+interval '1 hour',scopes=array['readonly'],revision=3 where id='00000000-0000-4000-b252-000000000004' and state='exchanging' and revision=1 returning id) select is((select count(*)::int from changed),0,'wrong revision cannot save');
with changed as (update public.space_discovery_connections set state='connected',pending_ciphertext=null,nonce_expires_at=null,tokens_ciphertext='v1.tokens',expires_at=now()+interval '1 hour',scopes=array['readonly'],revision=3 where id='00000000-0000-4000-b252-000000000004' and state='exchanging' and revision=2 returning id) select is((select count(*)::int from changed),1,'correct generation/revision saves connected tokens');
with changed as (update public.space_discovery_connections set state='revoked',tokens_ciphertext=null,expires_at=null,scopes='{}',revision=4 where id='00000000-0000-4000-b252-000000000004' and revision=3 returning id) select is((select count(*)::int from changed),1,'disconnect clears credentials');
with changed as (update public.space_discovery_connections set tokens_ciphertext='v1.stale',revision=4 where id='00000000-0000-4000-b252-000000000004' and state='connected' and revision=3 returning id) select is((select count(*)::int from changed),0,'stale refresh cannot resurrect revoked connection');
select is((select tokens_ciphertext from public.space_discovery_connections where id='00000000-0000-4000-b252-000000000004'),null,'revoked row contains no sealed tokens');
select throws_ok($$update public.space_discovery_connections set state='connected' where id='00000000-0000-4000-b252-000000000004'$$,'23514',null,'connected row requires a credential envelope');
select lives_ok($$insert into public.space_discovery_connections(space_id,provider,id,actor_profile_id,consent_id,property_url,property_scope,state) values('00000000-0000-4000-b252-000000000003','bing_webmaster','00000000-0000-4000-b252-000000000005','00000000-0000-4000-b252-000000000002','grant','https://example.com/','dedicated_property','revoked')$$,'other provider has independent generation');
reset role;
select * from finish();
rollback;
